helper='''namespace duckdb {

//! Selectivity assumed for substring-match filters (e.g. LIKE '%abc%' or contains(col, 'abc')),
//! which usually match far fewer rows than a generic filter.
static constexpr double SUBSTRING_MATCH_SELECTIVITY = 0.04;

static bool IsNonEmptyStringConstant(const Expression &expr) {
	if (expr.GetExpressionClass() != ExpressionClass::BOUND_CONSTANT) {
		return false;
	}
	auto &value = expr.Cast<BoundConstantExpression>().value;
	return value.type().id() == LogicalTypeId::VARCHAR && !value.IsNull() && !StringValue::Get(value).empty();
}

static bool IsSubstringMatchExpression(const Expression &expr) {
	if (expr.GetExpressionClass() != ExpressionClass::BOUND_FUNCTION) {
		return false;
	}
	auto &func = expr.Cast<BoundFunctionExpression>();
	if (func.children.size() < 2 || !IsNonEmptyStringConstant(*func.children[1])) {
		return false;
	}
	auto &name = func.function.name;
	if (name == "contains") {
		return func.children.size() == 2;
	}
	if (name == "~~" || name == "like_escape") {
		// the pattern must start with a wildcard and contain at least one literal character
		auto pattern = StringValue::Get(func.children[1]->Cast<BoundConstantExpression>().value);
		if (pattern[0] != '%') {
			return false;
		}
		for (auto c : pattern) {
			if (c != '%' && c != '_') {
				return true;
			}
		}
	}
	return false;
}

static bool IsSubstringMatchFilter(const TableFilter &filter) {
	switch (filter.filter_type) {
	case TableFilterType::EXPRESSION_FILTER:
		return IsSubstringMatchExpression(*filter.Cast<ExpressionFilter>().expr);
	case TableFilterType::CONJUNCTION_AND: {
		auto &conj = filter.Cast<ConjunctionAndFilter>();
		for (auto &child : conj.child_filters) {
			if (IsSubstringMatchFilter(*child)) {
				return true;
			}
		}
		return false;
	}
	default:
		return false;
	}
}
'''
s=s.replace('namespace duckdb {\n',helper,1)
s=s.replace('''		bool has_non_optional_filters = false;
''','''		bool has_non_optional_filters = false;
		bool has_substring_match_filter = false;
